+    CommentsStatus? status,
+    String? rootEventId,
+    int? rootEventKind,
+    String? rootAuthorPubkey,
+    String? rootAddressableId,
+    Map<String, Comment>? commentsById,
+    CommentsListError? error,
+    bool? isLoadingMore,
+    bool? hasMoreContent,
+    CommentsSortMode? sortMode,
+    Map<String, int>? replyCountsByCommentId,
+    int? newCommentCount,
+  }) {
